

# This file was *autogenerated* from the file check_01_norm_axioms.sage
from sage.all_cmdline import *   # import sage library

_sage_const_101 = Integer(101); _sage_const_2 = Integer(2); _sage_const_1 = Integer(1); _sage_const_3 = Integer(3); _sage_const_5 = Integer(5); _sage_const_8 = Integer(8); _sage_const_20 = Integer(20); _sage_const_1j = ComplexNumber(0, '1'); _sage_const_0 = Integer(0); _sage_const_1en12 = RealNumber('1e-12'); _sage_const_0p0 = RealNumber('0.0'); _sage_const_2p5 = RealNumber('2.5')# <def_matrix_norm> + <matrix_norm_triangle_inequality>: ノルムの公理
import os
_dir = os.path.dirname(os.path.abspath(__file__)) if "__file__" in dir() else "."
load(os.path.join(_dir, "../../_shared/operators.sage"))
import numpy as np
rng = np.random.default_rng(int(_sage_const_101 ))
rep = CheckReport("matrix_norm_triangle_inequality")
def nrm(A):
    return float(np.sqrt(np.sum(np.abs(A)**_sage_const_2 )))
for n in [_sage_const_1 ,_sage_const_2 ,_sage_const_3 ,_sage_const_5 ,_sage_const_8 ]:
    for _ in range(_sage_const_20 ):
        A = rng.normal(size=(n,n)) + _sage_const_1j *rng.normal(size=(n,n))
        B = rng.normal(size=(n,n)) + _sage_const_1j *rng.normal(size=(n,n))
        c = complex(rng.normal(), rng.normal())
        rep.truth(nrm(A) >= _sage_const_0 , f"n={n}: ノルムは非負")
        rep.close(nrm(c*A), abs(c)*nrm(A), f"n={n}: 斉次性")
        rep.truth(nrm(A+B) <= nrm(A)+nrm(B)+_sage_const_1en12 , f"n={n}: 三角不等式")
        # 定義（成分の平方和の平方根）どおりであること
        rep.close(nrm(A), np.sqrt(sum(abs(A[i,j])**_sage_const_2  for i in range(n) for j in range(n))), f"n={n}: 定義式")
    rep.truth(nrm(np.zeros((n,n))) == _sage_const_0p0 , f"n={n}: ||O|| = 0")
    A = rng.normal(size=(n,n)) + _sage_const_1j *rng.normal(size=(n,n))
    rep.truth(nrm(A) > _sage_const_0 , f"n={n}: A != O なら ||A|| > 0")
    # 三角不等式の等号（B = tA, t>0）
    t = _sage_const_2p5 
    rep.close(nrm(A + t*A), nrm(A) + nrm(t*A), f"n={n}: B = tA で等号")
rep.finish()

